#pragma once
#include "add_ability_profile131.hpp"
#include "remove_unit131.hpp"
#include "remove_ability131.hpp"
#include "unit_scale131.hpp"
namespace wht {
inline const AddAbilityProfile131* AddAbilityProfileFor131(unsigned build){for(const auto& p:addAbilityProfiles131)if(p.build==build)return &p;return nullptr;}
inline bool AddAbilityCode131(uintptr_t base,const AddAbilityProfile131& p){ResourceTextProfile131 code{p.build,0,0,0,0,0,p.code,p.count};return ResourceTextGuard131(base,code);}
inline bool ParseAddAbility131(const std::wstring& args,uint32_t& code,int& level){if(args.find(L'\0')!=args.npos||args.find_first_of(L"\r\n")!=args.npos)return false;std::wistringstream in(args);std::wstring raw,extra;if(!(in>>raw)||!ParseRemoveAbility131(raw,code))return false;level=1;in>>std::ws;if(in.eof())return true;long long n=0;if(!(in>>n)||in>>extra||n<1||n>10000)return false;level=int(n);return true;}
struct AddAbilitySource131 {RemoveUnitSource131 unit;RemoveAbilitySource131 ability;int level=0;};
inline bool SameAddUnit131(const AddAbilitySource131& a,const AddAbilitySource131& b){return SameRemoveUnit131(a.unit,b.unit)&&SameRemovalUnit131(a.ability,b.ability);}
inline bool SameAddAbility131(const AddAbilitySource131& a,const AddAbilitySource131& b){return SameAddUnit131(a,b)&&SameRemovalAbility131(a.ability,b.ability);}
inline bool ReadAddLevel131(uintptr_t base,const AddAbilityProfile131& p,AddAbilitySource131& v){if(!v.ability.ability){v.level=0;return true;}__try{if(!v.ability.abilityId.Valid())return false;const int stored=*reinterpret_cast<int*>(v.ability.ability+p.level);if(stored<0||stored>=10000)return false;v.level=stored+1;return true;}__except(1){return false;}}
template<class Selected> bool ReadAddAbility131(uintptr_t base,unsigned build,uint32_t code,Selected selected,AddAbilitySource131& out){const auto* p=AddAbilityProfileFor131(build);if(!p||!AddAbilityCode131(base,*p))return false;AddAbilitySource131 v;if(!ReadRemoveUnit131(base,build,selected,v.unit)||!ReadRemoveAbility131(base,build,code,selected,v.ability)||v.unit.unit!=v.ability.unit||!(v.unit.id==v.ability.id)||v.unit.world!=v.ability.world||v.unit.local!=v.ability.local||!ReadAddLevel131(base,*p,v)||!ValidRemoveUnit131(base,build,v.unit)||selected()!=v.unit.unit)return false;out=v;return true;}
using AddAbilityNative131=uintptr_t(__cdecl*)(uintptr_t,uint32_t,int,int,int);
inline bool InvokeAddAbility131(AddAbilityNative131 add,uintptr_t unit,uint32_t code){if(!add||!unit||!code)return false;__try{add(unit,code,0,0,0);return true;}__except(1){return false;}}
inline bool InvokeAbilityMaximum131(uintptr_t base,const AddAbilityProfile131& p,uintptr_t ability,int& out){if(!ability)return false;__try{out=reinterpret_cast<int(__thiscall*)(uintptr_t)>(base+p.maximum)(ability);return out>=1&&out<=10000;}__except(1){return false;}}
inline bool InvokeAbilityStep131(uintptr_t base,const AddAbilityProfile131& p,const RemoveAbilitySource131& v,bool up){if(!v.ability||!v.abilityTable)return false;__try{if(*reinterpret_cast<uintptr_t*>(v.ability)!=v.abilityTable||!(DropIdentity131(v.ability)==v.abilityId))return false;const auto fn=*reinterpret_cast<uintptr_t*>(v.abilityTable+(up?p.up:p.down));if(!ScaleMethod131(base,fn))return false;reinterpret_cast<void(__thiscall*)(uintptr_t)>(fn)(v.ability);return true;}__except(1){return false;}}
template<class Read> bool CreateAbilityNative131(uintptr_t base,unsigned build,uint32_t code,const AddAbilitySource131& source,Read read){const auto* p=AddAbilityProfileFor131(build);if(!p||!AddAbilityCode131(base,*p)||source.ability.ability)return false;AddAbilitySource131 current;if(!read(code,current)||!SameAddAbility131(source,current)||!InvokeRefreshAbility131(reinterpret_cast<RefreshAbilityNative131>(base+p->before),current.unit.unit))return false;if(!read(code,current)||!SameAddAbility131(source,current))return false;if(!InvokeAddAbility131(reinterpret_cast<AddAbilityNative131>(base+p->add),current.unit.unit,code))return false;if(!read(code,current)||!SameAddUnit131(source,current))return false;if(!InvokeRefreshAbility131(reinterpret_cast<RefreshAbilityNative131>(base+p->after),current.unit.unit))return false;if(!read(code,current)||!SameAddUnit131(source,current)||!current.ability.ability)return false;return InvokeRefreshAbility131(reinterpret_cast<RefreshAbilityNative131>(base+p->refresh),current.unit.unit);}
template<class Read,class Create,class Maximum,class Step,class Refresh> bool AddAbilityFlow131(const std::wstring& args,Read read,Create create,Maximum maximum,Step step,Refresh refresh,std::string& report){uint32_t code=0;int requested=1;if(!ParseAddAbility131(args,code,requested)){report="Usage: #sabi AHhb [level 1..10000] (hex rawcode accepted)";return false;}AddAbilitySource131 original,current,after;if(!read(code,original)||!read(code,current)||!SameAddAbility131(original,current)||original.level!=current.level){report="Add Ability: select a stable registered unit";return false;}bool added=false;auto fail=[&](const char* reason){report=std::string(added?"Ability added; ":"Add Ability: ")+reason;return false;};if(!current.ability.ability){const bool ok=create(code,current);if(!read(code,after)||!SameAddUnit131(original,after))return fail("unit changed during creation; update may have applied");added=after.ability.ability!=0;if(!ok||!added)return fail("creation or notification failed (unknown rawcode/map restriction)");current=after;}
 if(current.level<1||current.level>10000)return fail("native level unavailable");if(requested>1){int max=0;if(!maximum(current,max)||max<1||max>10000)return fail("native level limit unavailable");if(!read(code,after)||!SameAddAbility131(current,after)||current.level!=after.level)return fail("ability changed during limit query");current=after;const int target=(std::min)(requested,max);for(unsigned count=0;current.level!=target&&count<10000;++count){if(!read(code,after)||!SameAddAbility131(current,after)||current.level!=after.level)return fail("ability changed before level step");const bool up=current.level<target;if(!step(current,up))return fail("native level step failed; update may have applied");if(!read(code,after)||!SameAddAbility131(current,after)||after.level!=current.level+(up?1:-1))return fail("game did not confirm level step");current=after;}if(current.level!=target)return fail("level update incomplete");if(!refresh(current)||!read(code,after)||!SameAddAbility131(current,after)||after.level!=target)return fail("ability changed during panel refresh");current=after;}
 report=std::string(added?"Added Ability: ":"Existing Ability: ")+RemoveAbilityName131(code)+" | Level: "+std::to_string(current.level);return true;}
template<class Selected> bool AddAbilityCommand131(uintptr_t base,unsigned build,const std::wstring& args,Selected selected,std::string& report){const auto* p=AddAbilityProfileFor131(build);if(!p||!AddAbilityCode131(base,*p)){report="Add Ability: native profile mismatch";return false;}auto read=[&](uint32_t code,AddAbilitySource131& out){return ReadAddAbility131(base,build,code,selected,out);};return AddAbilityFlow131(args,read,[&](uint32_t code,const AddAbilitySource131& v){return CreateAbilityNative131(base,build,code,v,read);},[&](const AddAbilitySource131& v,int& max){return ValidRemoveUnit131(base,build,v.unit)&&InvokeAbilityMaximum131(base,*p,v.ability.ability,max);},[&](const AddAbilitySource131& v,bool up){return ValidRemoveUnit131(base,build,v.unit)&&InvokeAbilityStep131(base,*p,v.ability,up);},[&](const AddAbilitySource131& v){return ValidRemoveUnit131(base,build,v.unit)&&InvokeRefreshAbility131(reinterpret_cast<RefreshAbilityNative131>(base+p->refresh),v.unit.unit);},report);}
}
